public class Main {
static String queueOrder(String[] items) {
  java.util.ArrayDeque<String> q = new java.util.ArrayDeque<>();
  for (String item : items) q.addLast(item);
  StringBuilder sb = new StringBuilder();
  while (!q.isEmpty()) { if (sb.length() > 0) sb.append(","); sb.append(q.removeFirst()); }
  return sb.toString();
}
}
